use burn_autodiff::tensor::backend::AutodiffBackend;
use burn_autodiff::tensor::Tensor;
use burn_autodiff::TestAutodiffTensor;
use burn_tch::TchBackend;

// Harness entrypoint: must define fn body()
pub fn body() {
    let device = burn_tch::TchDevice::Cpu;

    let data_1 = [[6.0f32, 7.0f32],[9.0f32, -10.0f32]];
    let data_2 = [[0.0f32, -1.0f32],[3.0f32, 4.0f32]];

    let tensor_1: TestAutodiffTensor< TchBackend<f32> > =
        TestAutodiffTensor::from_data(data_1, &device).require_grad();
    let tensor_2: TestAutodiffTensor< TchBackend<f32> > =
        TestAutodiffTensor::from_data(data_2, &device).require_grad();

    let tensor_3 = tensor_1.clone().matmul(tensor_2.clone().abs());
    let grads = tensor_3.backward();

    let grad_1 = tensor_1.grad(&grads).unwrap();
    let grad_2 = tensor_2.grad(&grads).unwrap();

    // Record values and NaN flags. The probe framework will serialize scalars.
    let grad_1_vec: Vec<f32> = grad_1.clone().into_data().value;
    let grad_2_vec: Vec<f32> = grad_2.clone().into_data().value;

    let nan1 = grad_1_vec.iter().any(|x| x.is_nan());
    let nan2 = grad_2_vec.iter().any(|x| x.is_nan());

    probe_scalar("grad_1_nan", nan1 as i32 as f32);
    probe_scalar("grad_2_nan", nan2 as i32 as f32);

    // For a 2x2, record in row-major order.
    probe_scalar("grad_1_00", grad_1_vec[0]);
    probe_scalar("grad_1_01", grad_1_vec[1]);
    probe_scalar("grad_1_10", grad_1_vec[2]);
    probe_scalar("grad_1_11", grad_1_vec[3]);

    probe_scalar("grad_2_00", grad_2_vec[0]);
    probe_scalar("grad_2_01", grad_2_vec[1]);
    probe_scalar("grad_2_10", grad_2_vec[2]);
    probe_scalar("grad_2_11", grad_2_vec[3]);
}

